use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn lowest_common_ancestor(mut r:Option<Rc<RefCell<TreeNode>>>,p:Option<Rc<RefCell<TreeNode>>>,q:Option<Rc<RefCell<TreeNode>>>)->Option<Rc<RefCell<TreeNode>>>{let pv=p.unwrap().borrow().val;let qv=q.unwrap().borrow().val;while let Some(x)=r.clone(){let v=x.borrow().val;if pv<v&&qv<v{r=x.borrow().left.clone()}else if pv>v&&qv>v{r=x.borrow().right.clone()}else{return r}}None}}
